const daysAgo = (n) => {
  const d = new Date();
  d.setDate(d.getDate() - n);
  return d.toISOString();
};

const daysAhead = (n) => {
  const d = new Date();
  d.setDate(d.getDate() + n);
  return d.toISOString();
};

const books = [
  'The Pragmatic Programmer', 'Clean Code', '1984', 'Sapiens', 'Atomic Habits',
  'Deep Work', 'The Alchemist', 'Educated', 'Becoming', 'The Hobbit',
  'To Kill a Mockingbird', 'The Great Gatsby', 'Circe', 'The Night Circus',
  'The Lean Startup', 'Refactoring', 'Design Patterns', 'The Catcher in the Rye',
  'Harry Potter and the Sorcerer\'s Stone', 'The Lord of the Rings', 'Kite Runner',
  'Half of a Yellow Sun', 'Pride and Prejudice', 'Thinking, Fast and Slow',
  'The Immortal Life of Henrietta Lacks', 'Moneyball', 'The Signal and the Noise',
  'Black Swan', 'Antifragile', 'Dune', 'Foundation',
];

const authors = [
  'Andrew Hunt', 'Robert C. Martin', 'George Orwell', 'Yuval Noah Harari',
  'James Clear', 'Cal Newport', 'Paulo Coelho', 'Tara Westover', 'Michelle Obama',
  'J.R.R. Tolkien', 'Harper Lee', 'F. Scott Fitzgerald', 'Madeline Miller',
  'Erin Morgenstern', 'Eric Ries', 'Martin Fowler', 'Gang of Four', 'J.D. Salinger',
  'J.K. Rowling', 'J.R.R. Tolkien', 'Khaled Hosseini', 'Chimamanda Ngozi Adichie',
  'Jane Austen', 'Daniel Kahneman', 'Rebecca Skloot', 'Michael Lewis',
  'Nate Silver', 'Nassim Nicholas Taleb', 'Nassim Nicholas Taleb', 'Frank Herbert',
  'Isaac Asimov',
];

const statuses = ['returned', 'returned', 'issued', 'returned', 'overdue', 'issued', 'returned', 'lost'];

const profile = {
  id: 1,
  username: 'jdoe',
  full_name: 'Jane Doe',
  email: 'jane.doe@example.com',
  phone: '+1 555 0100',
  address: '123 Library Lane, Booktown',
  role: 'member',
  membership_id: 'MEM-2024-00187',
  member_since: daysAgo(420),
  currently_borrowed: 3,
  total_borrowed: 47,
  overdue_count: 2,
};

const borrowHistory = Array.from({ length: 40 }, (_, i) => {
  const issuedOffset = i * 7 + (i % 3);
  const issue = daysAgo(issuedOffset);
  const due = daysAgo(issuedOffset - 14);
  const status = statuses[i % statuses.length];
  const returned = status === 'returned' || status === 'lost';
  return {
    id: i + 1,
    book_title: books[i % books.length],
    book_author: authors[i % authors.length],
    issue_date: issue,
    due_date: due,
    return_date: returned ? daysAgo(issuedOffset - (i % 12) - 1) : null,
    status,
  };
});

export default { profile, borrowHistory };
